package org.sleepwell.app;
import android.content.Context;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.io.*;import java.security.*;import java.util.*;import java.util.function.BooleanSupplier;import java.util.zip.*;
/** Strict allowlisted relative signal snapshot. Never serializes a source record or sensor configuration. */
final class ResearchSignals {
 static final int MAX_NIGHTS=256,MAX_CANDIDATES=2000,MAX_PER_NIGHT=30000,MAX_EPOCHS=1000000;static final long MAX_BYTES=128L*1024*1024;
 static final class Entry {final String name,sha;final long bytes;Entry(String name,String sha,long bytes){this.name=name;this.sha=sha;this.bytes=bytes;}}
 static final class Snapshot implements AutoCloseable {final ResearchWorkspace workspace;final List<Entry> entries;final int days,nights,epochs,unknown,excluded,candidates;final long bytes;final Map<String,Integer> rejected;
  Snapshot(ResearchWorkspace workspace,List<Entry> entries,int days,int nights,int epochs,int unknown,int excluded,int candidates,long bytes,Map<String,Integer> rejected){this.workspace=workspace;this.entries=List.copyOf(entries);this.days=days;this.nights=nights;this.epochs=epochs;this.unknown=unknown;this.excluded=excluded;this.candidates=candidates;this.bytes=bytes;this.rejected=Map.copyOf(rejected);}
  void write(OutputStream destination,BooleanSupplier active)throws Exception{NightAudioArchive.active(active);try(ZipOutputStream zip=new ZipOutputStream(destination,java.nio.charset.StandardCharsets.UTF_8)){zip.setLevel(Deflater.BEST_SPEED);byte[] buffer=new byte[65536];for(Entry entry:entries){NightAudioArchive.active(active);ZipEntry item=new ZipEntry(entry.name);item.setTime(0);zip.putNextEntry(item);MessageDigest hash=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream input=new FileInputStream(workspace.file(entry.name))){for(int n;(n=input.read(buffer))!=-1;){NightAudioArchive.active(active);count+=n;if(count>entry.bytes)throw new IOException("The reviewed signal snapshot changed. Prepare it again.");hash.update(buffer,0,n);zip.write(buffer,0,n);}}if(count!=entry.bytes||!NightAudioArchive.hash(hash.digest()).equals(entry.sha))throw new IOException("The reviewed signal snapshot changed. Prepare it again.");zip.closeEntry();}NightAudioArchive.active(active);zip.finish();}}
  public void close()throws IOException{workspace.close();}
 }
 static final class Budget {long bytes;final BooleanSupplier active;Budget(BooleanSupplier active){this.active=active;}void take(int count)throws IOException{NightAudioArchive.active(active);bytes+=count;if(bytes>MAX_BYTES)throw limit();}}
 static final class Written implements AutoCloseable {final File file;final String name;final MessageDigest hash;final FileOutputStream output;final Budget budget;long bytes;Written(ResearchWorkspace workspace,String name,Budget budget)throws Exception{this.name=name;this.budget=budget;file=workspace.file(name);hash=MessageDigest.getInstance("SHA-256");output=new FileOutputStream(file);}void line(JSONObject row)throws Exception{byte[] bytes=(row.toString()+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8);budget.take(bytes.length);output.write(bytes);hash.update(bytes);this.bytes+=bytes.length;}Entry entry(){return new Entry(name,NightAudioArchive.hash(hash.digest()),bytes);}public void close()throws IOException{output.close();}}
 static final class Epoch {final long from,to;final Double value;final int samples;final String quality;Epoch(long from,long to,Double value,int samples,String quality){this.from=from;this.to=to;this.value=value;this.samples=samples;this.quality=quality;}}
 static final class Stats {int raw,accepted,measured,unknown,excluded;double max;final List<RecordIntervals.Span> measuredSpans=new ArrayList<>();}
 interface Epochs {void row(Epoch epoch)throws Exception;}
 private static IOException limit(){return new IOException("The signal selection exceeds 256 nights, 1,000,000 epochs or 128 MB. Choose a shorter window; nothing was truncated.");}
 private static boolean numeric(Cursor cursor,int column){int type=cursor.getType(column);return type==Cursor.FIELD_TYPE_INTEGER||type==Cursor.FIELD_TYPE_FLOAT;}
 private static boolean contained(List<RecordIntervals.Span> spans,long from,long to){for(RecordIntervals.Span span:spans)if(from>=span.start&&to<=span.end)return true;return false;}
 private static Stats scan(Store store,RecordEntry record,List<RecordIntervals.Span> eligible,BooleanSupplier active,Epochs consume)throws Exception{Stats stats=new Stats();long previous=record.rawStart;try(Cursor cursor=store.getReadableDatabase().rawQuery("SELECT start,time,movement,samples,signal_quality FROM epochs WHERE session=? ORDER BY time,start,id LIMIT "+(MAX_PER_NIGHT+1),new String[]{""+record.id})){while(cursor.moveToNext()){NightAudioArchive.active(active);if(++stats.raw>MAX_PER_NIGHT)throw limit();if(cursor.isNull(0)||cursor.isNull(1)||cursor.isNull(3)||!numeric(cursor,0)||!numeric(cursor,1)||!numeric(cursor,3)||!cursor.isNull(2)&&!numeric(cursor,2)){stats.unknown++;continue;}long from=cursor.getLong(0),to=cursor.getLong(1);double sampleNumber=cursor.getDouble(3);int samples=cursor.getInt(3);if(from<record.rawStart||to<=from||to>record.rawEnd||from<previous||cursor.getDouble(0)!=from||cursor.getDouble(1)!=to||sampleNumber!=samples||samples<0||samples>SensorProvenance.MAX_SAMPLES){stats.unknown++;continue;}previous=to;if(!contained(eligible,from,to)){stats.excluded++;continue;}Double value=cursor.isNull(2)?null:cursor.getDouble(2);String quality;if(record.sonar()){quality=cursor.isNull(4)?"":cursor.getString(4);try{SensorProvenance.evidence(value,quality,samples);}catch(IllegalArgumentException invalid){stats.unknown++;continue;}}else{if(!cursor.isNull(4)||value!=null&&(!Double.isFinite(value)||value<0||value>1e6||samples==0)){stats.unknown++;continue;}quality=value==null?"MISSING":"MEASURED";}stats.accepted++;if(value!=null){stats.measured++;stats.max=Math.max(stats.max,value);stats.measuredSpans.add(new RecordIntervals.Span(from,to));}if(consume!=null)consume.row(new Epoch(from,to,value,samples,quality));}}return stats;}
 private static void reject(Map<String,Integer> rejected,String why){rejected.merge(why,1,Integer::sum);}
 static Snapshot prepare(Context app,Store store,int days,long now,BooleanSupplier active,long admission)throws Exception{if(!Set.of(7,30,90).contains(days))throw new IOException("Choose a 7, 30 or 90 day window.");BackupRuntime.requireIdle(app,admission);ResearchWorkspace workspace=ResearchWorkspace.create(app);BooleanSupplier live=()->{BackupRuntime.requireIdle(app,admission);return active.getAsBoolean();};Budget budget=new Budget(live);List<Entry> entries=new ArrayList<>();Map<String,Integer> rejected=new LinkedHashMap<>();int nights=0,totalEpochs=0,unknown=0,excluded=0,candidates=0,rawEpochs=0;SQLiteDatabase db=null;boolean transaction=false;try{db=store.getReadableDatabase();db.beginTransactionNonExclusive();transaction=true;
  List<Long> ids=new ArrayList<>();try(Cursor cursor=db.rawQuery("SELECT id FROM sessions WHERE end IS NOT NULL AND end>=CAST(? AS INTEGER) AND end<=CAST(? AS INTEGER) ORDER BY id LIMIT "+(MAX_CANDIDATES+1),new String[]{""+(now-days*86400000L),""+now})){while(cursor.moveToNext()){NightAudioArchive.active(live);ids.add(cursor.getLong(0));if(ids.size()>MAX_CANDIDATES)throw new IOException("More than 2,000 closed records are in this window. Choose a shorter window.");}}candidates=ids.size();Collections.shuffle(ids,new SecureRandom());
  for(long id:ids){NightAudioArchive.active(live);RecordEntry record;try{record=Records.get(store,id);}catch(RuntimeException invalid){reject(rejected,"unreadable_record");continue;}if(!record.source.equals("tracked")||!record.origin.equals("local")||!record.healthConnect.isEmpty()){reject(rejected,"not_local_phone_tracking");continue;}if(!Set.of(SensorProvenance.MOTION,SensorProvenance.SONAR).contains(record.sensor)){reject(rejected,"unknown_sensor");continue;}try{SensorProvenance.validate(record.sensor,record.sensorConfig);}catch(IllegalArgumentException invalid){reject(rejected,"unsupported_sensor_metadata");continue;}if(record.clockChanged!=0||record.rawEnd<=record.rawStart||record.rawEnd-record.rawStart>SensorProvenance.MAX_SESSION||record.active==null||record.active<0||record.active>record.rawEnd-record.rawStart||record.edit.start<record.rawStart||record.edit.end>record.rawEnd||record.edit.end<=record.edit.start){reject(rejected,"unknown_or_changed_clock_bounds");continue;}List<RecordIntervals.Span> eligible=record.coverage();if(eligible.isEmpty()){reject(rejected,"no_eligible_coverage");continue;}Stats stats=scan(store,record,eligible,live,null);rawEpochs+=stats.raw;if(rawEpochs>MAX_EPOCHS)throw limit();if(stats.measured==0){reject(rejected,"no_valid_measured_epochs");unknown+=stats.unknown;excluded+=stats.excluded;continue;}if(++nights>MAX_NIGHTS)throw limit();String night=UUID.randomUUID().toString(),name="night-"+night+".jsonl";long basis=record.edit.start;Written writer=new Written(workspace,name,budget);try{
   writer.line(new JSONObject().put("type","recording").put("night_id",night).put("sensor_method",record.sonar()?"contactless_echo_change_v1":"phone_highpass_rms").put("selected_period_ms",record.edit.end-basis));
   for(RecordIntervals.Span span:eligible)writer.line(interval("eligible_coverage",span,basis,null));
   List<RecordIntervals.Span> pauses=RecordIntervals.intersect(record.pauses,basis,record.edit.end);for(RecordIntervals.Span span:pauses)writer.line(interval("gap",span,basis,"tracking_pause"));List<RecordIntervals.Span> outside=RecordIntervals.subtract(List.of(new RecordIntervals.Span(basis,record.edit.end)),eligible);for(RecordIntervals.Span span:RecordIntervals.subtract(outside,pauses))writer.line(interval("gap",span,basis,"app_coverage_exclusion"));for(RecordIntervals.Span span:RecordIntervals.subtract(eligible,stats.measuredSpans))writer.line(interval("gap",span,basis,"unavailable_or_unmeasured"));
   Stats written=scan(store,record,eligible,live,epoch->{Object value=epoch.value==null?JSONObject.NULL:stats.max==0?0:epoch.value/stats.max;writer.line(new JSONObject().put("type","epoch").put("from_ms",epoch.from-basis).put("to_ms",epoch.to-basis).put("movement_relative",value).put("samples",epoch.samples).put("quality",epoch.quality));});if(written.accepted!=stats.accepted||written.measured!=stats.measured||Double.compare(written.max,stats.max)!=0)throw new IOException("The recorded signal snapshot changed.");writer.line(new JSONObject().put("type","counts").put("exported_epochs",stats.accepted).put("measured_epochs",stats.measured).put("rejected_unknown_epochs",stats.unknown).put("excluded_partial_or_outside_coverage_epochs",stats.excluded));
  }finally{writer.close();}entries.add(writer.entry());totalEpochs+=stats.accepted;unknown+=stats.unknown;excluded+=stats.excluded;}
  JSONArray fileRows=new JSONArray();for(Entry entry:entries)fileRows.put(new JSONObject().put("file",entry.name).put("sha256",entry.sha).put("bytes",entry.bytes));JSONObject omissions=new JSONObject();for(Map.Entry<String,Integer> rejectedEntry:rejected.entrySet())omissions.put(rejectedEntry.getKey(),rejectedEntry.getValue());JSONObject manifest=new JSONObject().put("format","sleepwell-relative-research-signals").put("version",1).put("window_days",days).put("candidate_closed_records",candidates).put("selected_nights",nights).put("exported_epochs",totalEpochs).put("rejected_unknown_epochs",unknown).put("excluded_partial_or_outside_coverage_epochs",excluded).put("rejected_nights",omissions).put("files",fileRows).put("method","Closed local tracked phone/sonar nights only. Random IDs and shuffled night order are regenerated per preparation. Offsets start at each selected edited period, never at a calendar epoch. Movement is normalized by the maximum measured movement in that night; measured all-zero nights remain zero. Null means unavailable, never stillness. Whole stored intervals only, no interpolation; gaps include app-derived effective coverage exclusions (edits/accepted awake estimates) and pauses. Quality is the original contactless quality or MEASURED/MISSING phone aggregate status. Relative magnitudes cannot be compared across nights or sensors. These signals are not validated sleep stages, breathing or medical measurements.").put("excludes","Dates, wall clocks, time zones, database IDs, notes, tags, ratings, diaries, alarms, sound labels, raw audio, light/noise data, echo periodicity, sensor configurations, credentials, device IDs and coordinates.").put("privacy","This is not guaranteed anonymous. Duration, gaps and signal patterns may identify a person or night. No automatic upload or telemetry occurs; the user chooses the ZIP destination.");Written index=new Written(workspace,"manifest.json",budget);try{index.line(manifest);}finally{index.close();}entries.add(index.entry());NightAudioArchive.active(live);db.setTransactionSuccessful();transaction=false;db.endTransaction();return new Snapshot(workspace,entries,days,nights,totalEpochs,unknown,excluded,candidates,budget.bytes,rejected);
 }catch(Exception failed){try{workspace.close();}catch(IOException cleanup){failed.addSuppressed(cleanup);}throw failed;}finally{if(transaction)db.endTransaction();}}
 private static JSONObject interval(String type,RecordIntervals.Span span,long basis,String reason)throws JSONException{JSONObject row=new JSONObject().put("type",type).put("from_ms",span.start-basis).put("to_ms",span.end-basis);if(reason!=null)row.put("reason",reason);return row;}
}
